if(location.pathname.replace(/\/$/,'')==='/inscricao'){
document.title='Inscrição — Luta pela Comunidade';
document.querySelector('main').innerHTML=`<section class="detail-hero registration-intro"><p class="eyebrow">LUTA PELA COMUNIDADE · ATÉ 17 ANOS</p><h1>Um novo começo<br>no tatame.</h1><p class="lead">Solicitação de inscrição para Amavale, Valparaíso ou Vale do Carangola. O preenchimento deve ser feito pela mãe, pelo pai ou pelo responsável legal.</p></section><section class="section registration-layout"><form id="registration-form" novalidate><div id="registration-status" class="form-status" role="status">Verificando o serviço de envio…</div><fieldset><legend>01 · Dados do aluno</legend><div class="form-grid"><label class="wide">Nome completo do aluno<input name="studentName" autocomplete="off" required minlength="3" maxlength="120"></label><label>Data de nascimento<input type="date" name="birthDate" required aria-describedby="age-help"></label><label>Núcleo desejado<select name="unit" required><option value="">Selecione o núcleo</option><option value="amavale">Amavale</option><option value="valparaiso">Valparaíso</option><option value="vale-do-carangola">Vale do Carangola</option></select></label></div><p id="age-help" class="field-help">Idade máxima: 17 anos na data da solicitação.</p></fieldset><fieldset><legend>02 · Responsável legal</legend><div class="form-grid"><label class="wide">Nome completo do responsável<input name="guardianName" autocomplete="name" required minlength="3" maxlength="120"></label><label>Vínculo com o aluno<select name="relationship" required><option value="">Selecione</option><option>Mãe</option><option>Pai</option><option>Responsável legal</option></select></label><label>Telefone / WhatsApp<input type="tel" name="guardianPhone" autocomplete="tel" required maxlength="25" pattern="[+0-9 ()-]{10,25}" placeholder="(24) 99999-9999"></label><label class="wide">E-mail do responsável<input type="email" name="guardianEmail" autocomplete="email" required maxlength="254"></label></div></fieldset><fieldset><legend>03 · Documentos e foto (opcionais agora)</legend><p class="field-help">Pode se cadastrar sem anexos. Se tiver os documentos em mãos, envie agora. Caso contrário, combine o envio pelo WhatsApp com a secretaria, que completará seu cadastro. Arquivos legíveis, com até 3 MB cada. Documentos em PDF, JPG ou PNG; foto em JPG ou PNG. Se houver frente e verso, reúna ambos em um único PDF.</p><div class="upload-grid"><label>Documento do aluno<span>Documento de identificação ou certidão de nascimento.</span><input type="file" name="studentDocument" accept=".pdf,.jpg,.jpeg,.png"><small class="file-feedback"></small></label><label>Documento do responsável<span>Documento de identificação da pessoa que autoriza a participação.</span><input type="file" name="guardianDocument" accept=".pdf,.jpg,.jpeg,.png"><small class="file-feedback"></small></label><label>Atestado médico<span>Deve declarar aptidão para práticas esportivas. Será conferido pela equipe.</span><input type="file" name="medicalCertificate" accept=".pdf,.jpg,.jpeg,.png"><small class="file-feedback"></small></label><label>Foto para registro<span>Foto atual do aluno, com o rosto visível. Uso exclusivo no registro interno.</span><input type="file" name="photo" accept=".jpg,.jpeg,.png"><small class="file-feedback"></small></label></div></fieldset><fieldset class="consents"><legend>04 · Autorização do responsável</legend><label><input type="checkbox" name="participationConsent" required><span>Declaro ser mãe, pai ou responsável legal pelo aluno e <strong>autorizo sua participação nas atividades do projeto</strong>, após avaliação da documentação e confirmação da vaga.</span></label><label><input type="checkbox" name="medicalConsent" required><span>Estou ciente da <strong>exigência de atestado médico de aptidão para práticas esportivas</strong> e de que a participação depende da conferência desse documento pela equipe.</span></label><div class="privacy-note"><h3>Uso dos dados e documentos</h3><p>Os dados do aluno e do responsável, o atestado médico e a foto serão encaminhados à equipe do Luta pela Comunidade, realizado pela FJJE-Rio, para análise da inscrição, conferência documental e registro interno.</p><p>Destinatários: <strong>participante@lutapelacomunidade.com.br</strong> e <strong>tezzei@gmail.com</strong>. A foto não será autorizada para divulgação pública por este formulário. Para solicitar informações, correção ou exclusão, contate participante@lutapelacomunidade.com.br.</p></div><label><input type="checkbox" name="dataConsent" required><span><strong>Autorizo o tratamento e o envio dos dados e documentos</strong>, inclusive o atestado médico e a foto, para as finalidades e destinatários descritos acima.</span></label></fieldset><div class="honeypot" aria-hidden="true"><label>Site pessoal<input name="website" tabindex="-1" autocomplete="off"></label></div><div id="form-message" role="alert" tabindex="-1"></div><button id="submit-registration" type="submit" class="button" disabled>Enviar solicitação de inscrição</button><p class="field-help">Você pode enviar esta solicitação sem anexos. A secretaria orientará sobre os documentos pendentes. O envio não garante vaga. A autorização declarada será registrada com o nome do responsável, a data e o protocolo.</p></form><aside class="registration-aside"><p class="eyebrow">ANTES DE COMEÇAR</p><h2>Uma inscrição<br>com cuidado.</h2><ul><li>Participantes com até 17 anos.</li><li>Preenchimento pelo responsável legal.</li><li>Escolha de um dos três núcleos.</li><li>Documentos e foto podem ser enviados depois, à secretaria.</li><li>Participação condicionada à conferência do atestado e confirmação da vaga.</li></ul><p>As aulas do projeto são gratuitas.</p><a href="/#unidades" class="text-link">Conhecer os núcleos</a></aside></section>`;
const form=document.querySelector('#registration-form'),submit=document.querySelector('#submit-registration'),status=document.querySelector('#registration-status'),message=document.querySelector('#form-message');
let enabled=false,requestId=crypto.randomUUID();
const registrationFeedbackReady=import('/request-feedback.js');
const selected=new URLSearchParams(location.search).get('nucleo');if(['amavale','valparaiso','vale-do-carangola'].includes(selected))form.elements.unit.value=selected;
function age(){const b=form.elements.birthDate.value;if(!b)return -1;const [y,m,d]=b.split('-').map(Number);const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return +parts.year-y-((+parts.month<m||(+parts.month===m&&+parts.day<d))?1:0)}
function validateAge(){const a=age();form.elements.birthDate.setCustomValidity(a<0?'Confira a data de nascimento.':a>17?'A idade máxima para inscrição é 17 anos.':'');document.querySelector('#age-help').textContent=a>=0?`Idade: ${a} anos. Limite do projeto: 17 anos.`:'Idade máxima: 17 anos na data da solicitação.'}
form.elements.birthDate.addEventListener('change',validateAge);
fetch('/api/registration-status',{cache:'no-store'}).then(r=>r.json()).then(data=>{if(data.receipt_mode==='portal'){const note=form.querySelector('.privacy-note');note.querySelectorAll('p')[1].textContent='Os dados e arquivos serão armazenados em ambiente privado no Render, com acesso da equipe autorizada para analisar a inscrição e manter a ficha do aluno. Os avisos por email não incluem os documentos. A foto não está autorizada para divulgação pública. Para informações, correção ou exclusão, contate participante@lutapelacomunidade.com.br.'}}).catch(()=>{});
for(const input of form.querySelectorAll('input[type=file]'))input.addEventListener('change',()=>{const f=input.files[0];input.setCustomValidity(f&&f.size>3*1024*1024?'O limite é 3 MB por arquivo.':'');input.nextElementSibling.textContent=f?`${f.name} · ${(f.size/1024/1024).toFixed(2)} MB`:''});
form.addEventListener('input',()=>{requestId=crypto.randomUUID()});form.addEventListener('change',()=>{requestId=crypto.randomUUID()});
fetch('/api/registration-status',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject()).then(data=>{enabled=data.enabled===true;submit.disabled=!enabled;status.textContent=enabled?'Preencha seus dados. Documentos e foto são opcionais nesta etapa.':'Inscrições abertas. O envio por este formulário está temporariamente indisponível. Para orientações, entre em contato com participante@lutapelacomunidade.com.br. Aguarde a disponibilidade do envio antes de anexar documentos.'}).catch(()=>{status.textContent='Inscrições abertas. O envio por este formulário está temporariamente indisponível. Para orientações, entre em contato com participante@lutapelacomunidade.com.br. Aguarde a disponibilidade do envio antes de anexar documentos.'});
form.addEventListener('submit',async e=>{
 e.preventDefault();if(!enabled||submit.disabled)return;validateAge();if(!form.reportValidity())return;
 submit.disabled=true;submit.textContent='Enviando…';message.textContent='';const data=new FormData(form);data.set('requestId',requestId);
 try{const feedback=await registrationFeedbackReady;const result=await feedback.requestJson('/api/registrations',{method:'POST',body:data},'protocol');
  message.className='form-success';message.textContent=result.message+` Protocolo: ${result.protocol}`;form.reset();for(const el of form.querySelectorAll('.file-feedback'))el.textContent='';requestId=crypto.randomUUID();
 }catch(error){message.className='form-error';message.textContent=(error.name==='RequestFailure'?error.message:'Não foi possível iniciar a confirmação. Tente novamente em alguns minutos.')+' Seus campos e anexos foram preservados nesta página. Não atualize a página; use o mesmo botão para tentar novamente.';
 }finally{submit.disabled=false;submit.textContent='Enviar solicitação de inscrição';message.focus();message.scrollIntoView({block:'nearest'})}
});
}

